    cin >> n;
    int ans = n - 1;
    for (int i = 2; i < n; ++ i) {
        int j = n / i;
        int k = n % i;
        ans = max(ans, k + k - 1 + (i - 1) * j + (j - 1) * i);
    }
    cout << ans << endl;
    return 0;
}
